import subprocess,re,glob,os
branches=['rachel','monica','phoebe','joey','chandler','ross']
# collect friend commits
shas={}
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x1f%B%x1e',f'origin/friend/{b}'], text=True)
    for rec in out.split('\x1e'):
        rec=rec.strip('\n')
        if not rec: continue
        sha,msg=rec.split('\x1f',1)
        if 'Friend-Message: 1' in msg:
            shas[sha]=b
# collect source shas in main tree files
found=set()
for path in subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True).split():
    if re.match(r'S\d+/E\d+\.md',path):
        txt=subprocess.check_output(['git','show',f'origin/main:{path}'],text=True)
        for m in re.finditer(r'Source: friend/\w+ @ ([0-9a-f]{40})',txt):
            found.add(m.group(1))
missing=sorted(set(shas)-found)
print('friend commits:',len(shas),'recorded:',len(found),'missing:',len(missing))
for s in missing:
    print(s, shas[s])
PY
